// Params are an operation's path parameters, query (GET) or JSON body; "idempotency_key" becomes the header.
type Params map[string]any

// Error is an answer with "success": false.
type Error struct {
	Status  int
	Code    string
	Message string
}

func (e *Error) Error() string { return fmt.Sprintf("AceRDP %d %s: %s", e.Status, e.Code, e.Message) }

// Client talks to the API with one API key (panel: Settings > API).
type Client struct {
	APIKey  string
	BaseURL string
	HTTP    *http.Client
	// Retries: times a read, or a change with an idempotency key, is sent again after 429 or a server error.
	Retries int
	Sleep   func(time.Duration)
}

// New returns a client for the live site.
func New(apiKey string) *Client {
	return &Client{APIKey: apiKey, BaseURL: "https://acerdp.io", HTTP: &http.Client{Timeout: 60 * time.Second}, Retries: 2, Sleep: time.Sleep}
}

var placeholder = regexp.MustCompile(`\{(\w+)\}`)

// Request sends one operation and returns its "data".
func (c *Client) Request(ctx context.Context, method, path string, params Params) (json.RawMessage, error) {
	rest := Params{}
	for key, value := range params {
		rest[key] = value
	}
	var missing string
	path = placeholder.ReplaceAllStringFunc(path, func(match string) string {
		name := match[1 : len(match)-1]
		value, ok := rest[name]
		if !ok {
			missing = name
			return match
		}
		delete(rest, name)
		return url.PathEscape(fmt.Sprint(value))
	})
	if missing != "" {
		return nil, fmt.Errorf("missing %s", missing)
	}

	key, _ := rest["idempotency_key"].(string)
	delete(rest, "idempotency_key")
	target := strings.TrimRight(c.BaseURL, "/") + path
	var body []byte
	if method == http.MethodGet {
		query := url.Values{}
		for name, value := range rest {
			if value != nil {
				query.Set(name, fmt.Sprint(value))
			}
		}
		if len(query) > 0 {
			target += "?" + query.Encode()
		}
	} else {
		encoded, err := json.Marshal(rest)
		if err != nil {
			return nil, err
		}
		body = encoded
	}

	// A read, or a change with an idempotency key, cannot charge twice: only those are sent again.
	safe := method == http.MethodGet || key != ""
	for attempt := 0; ; attempt++ {
		req, err := http.NewRequestWithContext(ctx, method, target, bytes.NewReader(body))
		if err != nil {
			return nil, err
		}
		req.Header.Set("Authorization", "Bearer "+c.APIKey)
		req.Header.Set("Accept", "application/json")
		req.Header.Set("User-Agent", "acerdp-go")
		if body != nil {
			req.Header.Set("Content-Type", "application/json")
		}
		if key != "" {
			req.Header.Set("Idempotency-Key", key)
		}
		res, err := c.HTTP.Do(req)
		if err != nil {
			return nil, err
		}
		raw, err := io.ReadAll(res.Body)
		_ = res.Body.Close()
		if err != nil {
			return nil, err
		}
		if safe && attempt < c.Retries && (res.StatusCode == http.StatusTooManyRequests || res.StatusCode >= 500) {
			wait := time.Duration(1<<attempt) * time.Second
			if seconds, convErr := strconv.Atoi(res.Header.Get("Retry-After")); convErr == nil && seconds > 0 {
				wait = time.Duration(min(seconds, 60)) * time.Second
			}
			c.Sleep(wait)
			continue
		}

		var answer struct {
			Success *bool           `json:"success"`
			Data    json.RawMessage `json:"data"`
			Error   *struct {
				Code    string `json:"code"`
				Message string `json:"message"`
			} `json:"error"`
		}
		_ = json.Unmarshal(raw, &answer)
		if res.StatusCode >= 400 || (answer.Success != nil && !*answer.Success) {
			apiErr := &Error{Status: res.StatusCode, Code: "HTTP_ERROR", Message: http.StatusText(res.StatusCode)}
			if answer.Error != nil {
				apiErr.Code, apiErr.Message = answer.Error.Code, answer.Error.Message
			}
			return nil, apiErr
		}
		return answer.Data, nil
	}
}

// WaitUntilReady polls a new or reinstalled server's setup until it is done.
func (c *Client) WaitUntilReady(ctx context.Context, server string, interval, timeout time.Duration) (json.RawMessage, error) {
	deadline := time.Now().Add(timeout)
	for {
		data, err := c.GetProvisioningStatus(ctx, Params{"server": server})
		if err != nil {
			return nil, err
		}
		var status struct {
			Status string `json:"status"`
		}
		_ = json.Unmarshal(data, &status)
		switch status.Status {
		case "completed":
			return data, nil
		case "failed":
			return nil, &Error{Code: "BUILD_FAILED", Message: "The build failed; the price was refunded."}
		}
		if time.Now().After(deadline) {
			return nil, &Error{Code: "WAIT_TIMED_OUT", Message: "The server was not ready in time."}
		}
		c.Sleep(interval)
	}
}

